repositories {
    google()
    mavenCentral()
    gradlePluginPortal()
    maven(url = "https://jitpack.io")
    // Flutter embedding and the plugins used by flutter_ui resolve from here.
    maven(url = "https://storage.googleapis.com/download.flutter.io")
    // Generated by `cd flutter_ui && flutter build aar --no-profile`; build output only, never committed.
    // Absolute on purpose: `allprojects` applies this script to every project and Project.uri reads a
    // relative path against the project's own directory, so :app would look in app/flutter_ui/... and
    // silently fail to find the module.
    maven(url = uri("${rootProject.projectDir}/flutter_ui/build/host/outputs/repo"))
}